import dataclasses
import datetime as dt
import sys
import traceback
import types
import uuid

import sqlalchemy as sa
from sqlalchemy.orm import sessionmaker

import tests._database as database
from app.platform.schemas.text import length, normalize

BOUND = 200
LINE_BREAKS = (0x000A, 0x000B, 0x000C, 0x000D, 0x0085, 0x2028, 0x2029)

url = database.create_database()
engine = sa.create_engine(url)
with engine.begin() as connection:
    connection.execute(
        sa.text(
            "CREATE TABLE todo_tasks (id uuid PRIMARY KEY, text varchar(200) NOT NULL, "
            "done boolean NOT NULL, created_at timestamptz NOT NULL)"
        )
    )
    connection.execute(sa.text("CREATE INDEX ix_todo_tasks_created_at_id ON todo_tasks (created_at, id)"))
factory = sessionmaker(bind=engine)


class TodoTaskNotFoundError(Exception):
    pass


class TodoTaskTextEmptyError(Exception):
    pass


class TodoTaskTextMultilineError(Exception):
    pass


class TodoTaskTextTooLongError(Exception):
    pass


@dataclasses.dataclass
class Read:
    id: uuid.UUID
    text: str
    done: bool
    created_at: dt.datetime


@dataclasses.dataclass
class Page:
    items: list
    total: int


service = types.ModuleType("app.contexts.todo_list.services.todo_tasks")
service.SessionLocal = factory
MODE = {"correction": "statement", "marking": "statement"}


def _judged(text: str) -> str:
    text = normalize(text)
    if not text:
        raise TodoTaskTextEmptyError
    if any(chr(code) in text for code in LINE_BREAKS):
        raise TodoTaskTextMultilineError
    if length(text) > BOUND:
        raise TodoTaskTextTooLongError
    return text


def _read(row) -> Read:
    return Read(id=row[0], text=row[1], done=row[2], created_at=row[3])


def add_todo_task(*, text: str) -> Read:
    judged = _judged(text)
    with service.SessionLocal() as session:
        row = session.execute(
            sa.text(
                "INSERT INTO todo_tasks (id, text, done, created_at) VALUES (:id, :text, false, :at) "
                "RETURNING id, text, done, created_at"
            ),
            {"id": uuid.uuid4(), "text": judged, "at": dt.datetime.now(dt.UTC)},
        ).one()
        session.commit()
        return _read(row)


def list_todo_tasks() -> Page:
    with service.SessionLocal() as session:
        rows = session.execute(
            sa.text("SELECT id, text, done, created_at FROM todo_tasks ORDER BY created_at DESC, id DESC")
        ).all()
    return Page(items=[_read(r) for r in rows], total=len(rows))


def correct_todo_task(todo_task_id, *, text: str) -> Read:
    judged = _judged(text)
    with service.SessionLocal() as session:
        if MODE["correction"] == "write-back":
            read = session.execute(sa.text("SELECT done FROM todo_tasks WHERE id = :id"), {"id": todo_task_id}).first()
            if read is None:
                raise TodoTaskNotFoundError
            row = session.execute(
                sa.text("UPDATE todo_tasks SET text = :text, done = :done WHERE id = :id RETURNING id, text, done, created_at"),
                {"id": todo_task_id, "text": judged, "done": read[0]},
            ).first()
        elif MODE["correction"] == "upsert":
            row = session.execute(
                sa.text(
                    "INSERT INTO todo_tasks (id, text, done, created_at) VALUES (:id, :text, false, :at) "
                    "ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text RETURNING id, text, done, created_at"
                ),
