        session.commit()
        return _read(row)


def mark_todo_task(todo_task_id, *, done: bool) -> Read:
    with service.SessionLocal() as session:
        if MODE["marking"] == "flip":
            statement = "UPDATE todo_tasks SET done = NOT done WHERE id = :id RETURNING id, text, done, created_at"
            params = {"id": todo_task_id}
        else:
            statement = "UPDATE todo_tasks SET done = :done WHERE id = :id RETURNING id, text, done, created_at"
            params = {"id": todo_task_id, "done": done}
        row = session.execute(sa.text(statement), params).first()
        if row is None:
            raise TodoTaskNotFoundError
        session.commit()
        return _read(row)


def delete_todo_task(todo_task_id) -> None:
    with service.SessionLocal() as session:
        row = session.execute(sa.text("DELETE FROM todo_tasks WHERE id = :id RETURNING id"), {"id": todo_task_id}).first()
        if row is None:
            raise TodoTaskNotFoundError
        session.commit()


