        "add_todo_task", "list_todo_tasks", "correct_todo_task", "mark_todo_task", "delete_todo_task",
        "TodoTaskNotFoundError", "TodoTaskTextEmptyError", "TodoTaskTextMultilineError", "TodoTaskTextTooLongError",
    }:
        setattr(service, name, value)

model = types.ModuleType("app.contexts.todo_list.models.todo_task")
model.TODO_TASK_TEXT_MAX_LENGTH = BOUND
for name in (
    "app.contexts.todo_list", "app.contexts.todo_list.services", "app.contexts.todo_list.models",
):
