sys.modules["app.contexts.todo_list.services.todo_tasks"] = service
sys.modules["app.contexts.todo_list.models.todo_task"] = model

import tests.integration.test_todo_tasks_concurrency as concurrency  # noqa: E402
import tests.integration.test_todo_tasks_service as service_tests  # noqa: E402


def empty() -> None:
    with engine.begin() as connection:
