    MODE.update({"correction": "statement", "marking": "statement"})
    return verdicts


def show(title: str, verdicts: dict[str, str]) -> None:
    print(f"\n== {title}")
    for name, verdict in verdicts.items():
        print(f"  {verdict[:4]}  {name}  {verdict[5:] if verdict != 'pass' else ''}")


try:
    show("service tests, correct reference", run(service_tests, {}))
    show("concurrency tests, correct reference", run(concurrency, {}))
    show("concurrency tests, write-back correction", run(concurrency, {"correction": "write-back"}))
    show("concurrency tests, flipping marking", run(concurrency, {"marking": "flip"}))
    show("concurrency tests, upsert correction", run(concurrency, {"correction": "upsert"}))
    show("service tests, flipping marking", run(service_tests, {"marking": "flip"}))
    show("service tests, upsert correction", run(service_tests, {"correction": "upsert"}))
except Exception:
    traceback.print_exc()
finally:
